package com.contenthub.config;
import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.data.redis.cache.RedisCacheConfiguration;import org.springframework.data.redis.cache.RedisCacheManager;import org.springframework.data.redis.connection.RedisConnectionFactory;import org.springframework.data.redis.serializer.GenericJackson2JsonRedisSerializer;import org.springframework.data.redis.serializer.RedisSerializationContext;import java.time.Duration;
@Configuration public class RedisCacheConfig{@Bean RedisCacheManager cacheManager(RedisConnectionFactory factory){var serializer=new GenericJackson2JsonRedisSerializer();var config=RedisCacheConfiguration.defaultCacheConfig().entryTtl(Duration.ofMinutes(5)).serializeValuesWith(RedisSerializationContext.SerializationPair.fromSerializer(serializer));return RedisCacheManager.builder(factory).cacheDefaults(config).build();}}